def preguntas_de(m):
    voc = m["vocabulario"]
    preguntas = []
    for i, (emoji, en, _) in enumerate(voc):
        otros = [v[1] for j, v in enumerate(voc) if j != i]
        preguntas.append((emoji, "What is it?", en, [otros[i % len(otros)], otros[(i + 3) % len(otros)]]))
    for i in (0, 2, 4, 6):
        emoji, en, es = voc[i]
        otros = [v[1] for j, v in enumerate(voc) if j != i]
        preguntas.append((emoji, f"How do you say «{es}» in English?", en, [otros[(i + 1) % len(otros)], otros[(i + 4) % len(otros)]]))
    for emoji, frase, correcta, distractores in m["huecos"]:
        preguntas.append((emoji, f"Complete: {frase}", correcta, distractores))
    for emoji, es, en, distractores in m["frases"]:
        preguntas.append((emoji, f"«{es}» in English is…", en, distractores))
    return preguntas


MUNDOS = [{"titulo": m["titulo"], "emoji": m["emoji"], "semana": m["semana"],
           "descripcion": f"{m['temas']}. Estructura: {m['estructura']}",
           "preguntas": preguntas_de(m)} for m in PLAN]

assert len(MUNDOS) == 16 and all(len(m["preguntas"]) == 24 for m in MUNDOS)
for m in MUNDOS:
    for _, _, correcta, distractores in m["preguntas"]:
        assert correcta not in distractores and len(set(distractores)) == len(distractores), (m["titulo"], correcta)
